#!/usr/bin/env node
/*
 * Validate the rendered HTML with html-validate.
 *
 *   bundle exec jekyll build
 *   node scripts/check-html.mjs
 *
 * Validates the files in _site (the thing that is actually deployed), not the
 * Jekyll sources: the sources are fragments with front matter and Liquid, so
 * they are not valid HTML documents on their own.  Antora's output under
 * _site/docs is generated by a separate toolchain and is skipped.
 *
 * Exit code 1 when any error-severity message is reported.
 */
import { readFileSync, readdirSync, statSync } from 'node:fs'
import path from 'node:path'
import process from 'node:process'
import { HtmlValidate } from 'html-validate'

const ROOT = process.cwd()
const SITE = path.join(ROOT, '_site')
const SKIP = new Set(['docs'])

const config = JSON.parse(readFileSync(path.join(ROOT, '.htmlvalidate.json'), 'utf8'))
const htmlvalidate = new HtmlValidate(config)
const MAX_PER_PAGE = 8

function collect(dir, out = []) {
  for (const entry of readdirSync(dir, { withFileTypes: true })) {
    if (entry.isDirectory()) {
      if (entry.name.startsWith('.') || SKIP.has(entry.name)) continue
      collect(path.join(dir, entry.name), out)
    } else if (entry.name.endsWith('.html')) {
      out.push(path.join(dir, entry.name))
    }
  }
  return out
}

if (!statSync(SITE, { throwIfNoEntry: false })) {
  console.error('_site not found — run `bundle exec jekyll build` first.')
  process.exit(1)
}

const files = collect(SITE).sort()
const byRule = new Map()
let pagesWithErrors = 0
let total = 0

for (const file of files) {
  const report = await htmlvalidate.validateFile(file)
  const messages = report.results.flatMap((result) => result.messages)
  if (!messages.length) continue
  pagesWithErrors += 1
  total += messages.length
  for (const message of messages) {
    byRule.set(message.ruleId, (byRule.get(message.ruleId) || 0) + 1)
  }
  const relative = path.relative(ROOT, file)
  for (const message of messages.slice(0, MAX_PER_PAGE)) {
    console.log(`${relative}:${message.line}:${message.column}  ${message.ruleId}  ${message.message}`)
  }
  if (messages.length > MAX_PER_PAGE) {
    console.log(`${relative}: … ${messages.length - MAX_PER_PAGE} more`)
  }
}

if (!total) {
  console.log(`HTML check passed: ${files.length} pages, no problems.`)
  process.exit(0)
}

console.log(`\n${total} problem(s) in ${pagesWithErrors} of ${files.length} pages`)
for (const [rule, count] of [...byRule].sort((a, b) => b[1] - a[1])) {
  console.log(`  ${String(count).padStart(5)}  ${rule}`)
}
process.exit(1)
